import crypto from 'node:crypto';
import { v2 as cloudinary } from 'cloudinary';
import { config } from '../config/env.js';
import { ApiError } from '../utils/ApiError.js';
import { logger } from '../utils/logger.js';

// Files are stored as resource_type "raw" + type "authenticated": they have no public delivery
// URL. Access is only via short-lived signed links generated by this backend (API secret never
// leaves the server). Public IDs are random UUIDs, so file names (which can contain the user's
// name) never appear in Cloudinary paths.
const RESOURCE_TYPE = 'raw';
const DELIVERY_TYPE = 'authenticated';
const UPLOAD_TIMEOUT_MS = 60_000;

export const STORAGE_FOLDERS = { master: 'resumes/master', customized: 'resumes/customized' };

let configured = false;
function client() {
  const { cloudName, apiKey, apiSecret } = config.cloudinary;
  if (!cloudName || !apiKey || !apiSecret) {
    throw ApiError.serviceUnavailable('File storage is not configured on the server.', { code: 'STORAGE_NOT_CONFIGURED' });
  }
  if (!configured) {
    cloudinary.config({ cloud_name: cloudName, api_key: apiKey, api_secret: apiSecret, secure: true });
    configured = true;
  }
  return cloudinary;
}

const storageFailure = (operation, err) => {
  // Cloudinary error messages describe the API failure; they never contain file contents.
  logger.error(`Cloudinary ${operation} failed`, { httpCode: err?.http_code, error: err?.message });
  return ApiError.badGateway('File storage is temporarily unavailable. Please try again.', { code: 'STORAGE_ERROR' });
};

export const cloudinaryStorage = {
  /** Uploads PDF bytes privately. Resolves { publicId, bytes }. */
  uploadPdf(buffer, { folder }) {
    const cld = client();
    return new Promise((resolve, reject) => {
      const stream = cld.uploader.upload_stream(
        {
          resource_type: RESOURCE_TYPE,
          type: DELIVERY_TYPE,
          folder,
          public_id: `${crypto.randomUUID()}.pdf`, // raw assets keep the extension in the public id
          overwrite: false,
          use_filename: false,
          unique_filename: false,
          timeout: UPLOAD_TIMEOUT_MS,
        },
        (err, result) => (err ? reject(storageFailure('upload', err)) : resolve({ publicId: result.public_id, bytes: result.bytes })),
      );
      stream.end(buffer);
    });
  },

  /** Deletes an asset. "not found" counts as success, so deletion is idempotent. */
  async deleteFile(publicId) {
    const cld = client();
    let result;
    try {
      result = await cld.uploader.destroy(publicId, { resource_type: RESOURCE_TYPE, type: DELIVERY_TYPE, invalidate: true });
    } catch (err) {
      throw storageFailure('delete', err);
    }
    if (result?.result !== 'ok' && result?.result !== 'not found') throw storageFailure('delete', new Error(`unexpected result: ${result?.result}`));
  },

  /** Signed, expiring download URL for an asset. */
  getSignedUrl(publicId, { ttlSeconds = config.cloudinary.signedUrlTtlSeconds, attachment = true } = {}) {
    const cld = client();
    const expiresAt = Math.floor(Date.now() / 1000) + ttlSeconds;
    const url = cld.utils.private_download_url(publicId, '', {
      resource_type: RESOURCE_TYPE,
      type: DELIVERY_TYPE,
      expires_at: expiresAt,
      attachment,
    });
    return { url, expiresAt: new Date(expiresAt * 1000).toISOString() };
  },

  /** Downloads an asset's bytes server-side (used to stream previews to the authenticated owner). */
  async fetchFile(publicId, { maxBytes = config.upload.maxBytes * 2 } = {}) {
    const { url } = this.getSignedUrl(publicId, { ttlSeconds: 60, attachment: false });
    let res;
    try {
      res = await fetch(url, { signal: AbortSignal.timeout(30_000) });
    } catch (err) {
      throw storageFailure('download', err);
    }
    if (res.status === 404) throw ApiError.notFound('The stored file is missing.', { code: 'FILE_MISSING' });
    if (!res.ok) throw storageFailure('download', new Error(`HTTP ${res.status}`));
    const buffer = Buffer.from(await res.arrayBuffer());
    if (buffer.length > maxBytes) throw storageFailure('download', new Error('file larger than expected'));
    return buffer;
  },
};
